# mryt233 改（2026-11-10）：保存回执只写简体 / 英文，其余语言用英文占位。
SAVE_RESULT_TEXT = {
    "zh_cn": {
        "text.orients_hotpot_chronicles.config.msg.memory_only": "没能写入配置文件，改动只在本次游戏有效：%s",
        "text.orients_hotpot_chronicles.config.msg.save_failed": "没能应用改动，原配置文件已保留：%s",
        "text.orients_hotpot_chronicles.config.msg.broken_backup": "原配置无效，已备份为 %s。请核对后再关闭此页。",
    },
    "en_us": {
        "text.orients_hotpot_chronicles.config.msg.memory_only": "Could not write the config file. Changes apply only to this session: %s",
        "text.orients_hotpot_chronicles.config.msg.save_failed": "Changes were not applied. The original config was kept: %s",
        "text.orients_hotpot_chronicles.config.msg.broken_backup": "The invalid original config was backed up as %s. Review it before closing this page.",
    },
}
RETIRED_KEYS = ['resourcePack.orients_hotpot_chronicles.hotpot_assets', 'text.orients_hotpot_chronicles.screen.base', 'text.orients_hotpot_chronicles.screen.temp', 'text.orients_hotpot_chronicles.screen.stove.seconds', 'text.orients_hotpot_chronicles.screen.stove.waiting.short', 'text.orients_hotpot_chronicles.msg.aim_at_pot', 'text.orients_hotpot_chronicles.msg.detach_hint', 'text.orients_hotpot_chronicles.msg.scoop_need_bowl', 'text.orients_hotpot_chronicles.msg.station_out', 'text.orients_hotpot_chronicles.screen.sauce.hint']


def main():
    cauldron_key = full_key("block.drink_cauldron")
    for code in ("zh_cn", "en_us"):
        source = ROOTS[0] / MODID / f"lang/{code}.json"
        text = source.read_text(encoding="utf-8")
        values = json.loads(text)
        changed = any(key in values for key in RETIRED_KEYS)
        for key in RETIRED_KEYS:
            values.pop(key, None)
        for key, value in SAVE_RESULT_TEXT[code].items():
            if values.get(key) != value:
                values[key] = value
                changed = True
        if values.get(cauldron_key) != DRINK_CAULDRON_TEXT[code]:
            values[cauldron_key] = DRINK_CAULDRON_TEXT[code]
            changed = True
        for k, v in BOARD_MSG_TEXT[code].items():
            if values.get(k) != v:
                values[k] = v
                changed = True
        if changed:
            write(source, values, ensure_ascii=False)
    en = json.loads((ROOTS[0] / MODID / "lang/en_us.json").read_text(encoding="utf-8"))
    problems = []
    for code, table in L.items():
        by_full = {full_key(k): v for k, v in table.items()}
        by_full.update(SAVE_RESULT_TEXT["en_us"])
        # mryt233：未知汤底尚未翻译的语言使用英文占位。
        by_full[full_key("soup.unknown")] = "Unknown soup"
        by_full[full_key("sauce.unknown")] = "Unknown seasoning"
        for wood, name in zip(TABLE_WOODS, TABLE_NAMES[code]):
            by_full[full_key(f"block.{wood}_hotpot_table")] = name
        for wood, name in zip(TABLE_WOODS, BENCH_NAMES[code]):
            by_full[full_key(f"block.{wood}_stool")] = name
        by_full[f"entity.{MODID}.seat"] = SEAT_NAMES[code]
        by_full.update(PLATE_TEXT[code])
        by_full.update(TALL_TEXT[code])
        by_full.update(SUBTAB_TEXT[code])
        by_full.update(TRIPE_TEXT[code])
        by_full.update(BOWL_DRINK_TEXT[code])
        by_full.update(SAUCE_TEXT[code])
        by_full.update(SAUCE_GUIDE_TEXT[code])
        by_full.update(CUTTING_TEXT[code])
        by_full.update(POTATO_TOFU_TEXT[code])
        by_full.update(MEATBALL_TEXT[code])
        by_full.update(SAUCE_UI_TEXT[code])
        by_full.update({full_key(k): v for k, v in CONFIG_UI_TEXT[code].items()})
        by_full.update(R136D_TEXT[code])
        by_full.update(R137D_TEXT[code])
        by_full.update(R139_ADV_TEXT[code])
        by_full.update(R139_TEXT[code])
        by_full.update(R146A_CONFIG_TEXT[code])
        by_full.update(R146A_SAUCE_BOTTLE_TEXT[code])
        by_full.update(R146B_APRON_TEXT[code])
        # mryt233 改（r146f）：其他语言只补英文占位，留待统一翻译。
        by_full.update({
            "text.orients_hotpot_chronicles.screen.sauce.page": "Page %s / %s",
            "text.orients_hotpot_chronicles.screen.sauce.previous_page": "Previous page",
            "text.orients_hotpot_chronicles.screen.sauce.next_page": "Next page",
        })
        by_full.update(dict(zip(TAG_KEYS, TAG_TEXT[code])))
        by_full[cauldron_key] = DRINK_CAULDRON_TEXT[code]
        by_full.update(BOARD_MSG_TEXT[code])
        by_full[f"block.{MODID}.tall_brick_stove_top"] = TALL_TEXT[code][f"block.{MODID}.tall_brick_stove"]
        # 新物品的译文（tools/new_item.py 写进 tools/lang_items.json，mryt233 2026-11-01）；审核过的 lang_overrides 仍然盖在最上面
        items_file = MOD / "tools" / "lang_items.json"
        if items_file.exists():
            by_full.update(json.loads(items_file.read_text(encoding="utf-8")).get(code, {}))
        # 审核过的发布版译文（2026-10-25）：translate_sync.py import 写进 lang_overrides/<语言>.json，盖在上面的表上
        override = MOD / "tools" / "lang_overrides" / f"{code}.json"
        if override.exists():
            by_full.update(json.loads(override.read_text(encoding="utf-8")))
        # mryt233 改（r146d）：旧译文错误地暗示多款饮料；先用英文占位，后续审核的新译文仍可覆盖。
        old_author_descriptions = {
            "ru_ru": "Выпейте один из любимых напитков автора",
            "de_de": "Trink eines der Lieblingsgetränke des Autors",
            "fr_fr": "Buvez l'une des boissons préférées de l'auteur",
            "es_es": "Bebe una de las bebidas favoritas del autor",
            "pt_br": "Beba uma das bebidas favoritas do autor",
        }
        author_key = f"advancements.{MODID}.authors_pick.description"
        if code in old_author_descriptions and by_full.get(author_key) == old_author_descriptions[code]:
            by_full[author_key] = en[author_key]
        out = OrderedDict()
        for key, en_value in en.items():
            if key not in by_full:
                problems.append(f"{code}: 缺少 {key}")
                continue
            value = by_full[key]
            if sorted(PLACEHOLDER.findall(value)) != sorted(PLACEHOLDER.findall(en_value)):
                problems.append(f"{code}: {key} 占位符和英文不一致")
            out[key] = value
        extra = set(by_full) - set(en)
        problems += [f"{code}: 英文里没有 {k}" for k in sorted(extra)]
        for root in ROOTS:
            f = root / MODID / f"lang/{code}.json"
            write(f, out, ensure_ascii=False)
    if problems:
        print("\n".join(problems))
        sys.exit(1)
    print(f"已生成 {len(L)} 种语言：{', '.join(L)}（每种 {len(en)} 条）")


def sync_r146e_tutorial_placeholders():
    """mryt233 改：新玩法只复制简体原文作占位，不翻译、不覆盖其他章节的既有译文。"""
    source = MOD / "tutorial/content"
    ware = (source / "tableware.md").read_text(encoding="utf-8")
    start = ware.index("- **开锅界面**", ware.index("{{recipe:bamboo_chopsticks}}"))
    end = ware.index("{{icons:bamboo_chopsticks,chopstick_rest}}", start)
    bullets = ware[start:end]
    preview = (source / "preview.md").read_text(encoding="utf-8")
    start = preview.index("## 竹筷摆桌与架碗 {#r146e}")
    end = preview.index("\n## ", start + 3)
    section = preview[start:end]
    change = next(line for line in (source / "changelog.md").read_text(encoding="utf-8").splitlines()
                  if "<!--清单#139-->" in line)
    for folder in ("content-en", "content-zh-tw"):
        for slug in ("tableware", "preview", "changelog"):
            path = MOD / "tutorial" / folder / (slug + ".md")
            text = path.read_text(encoding="utf-8")
            # 已有占位（或以后已经翻译过）不重复生成。
            if "清单#139" in text:
                continue
            note = "<!-- mryt233 改：r146e 简体原文占位，待翻译。 -->\n"
            if slug == "tableware":
                start = text.index("\n- ", text.index("{{recipe:bamboo_chopsticks}}")) + 1
                end = text.index("{{icons:bamboo_chopsticks,chopstick_rest}}", start)
                text = text[:start] + note + bullets + text[end:]
            elif slug == "preview":
                start = text.index("\n## ") + 1
                text = text[:start] + note + section + "\n\n" + text[start:]
            else:
                start = text.index("\n", text.index("{#unreleased}")) + 1
                text = text[:start] + "\n" + note + change + "\n" + text[start:]
            path.write_text(text, encoding="utf-8")


if __name__ == "__main__":
    main()
    # mryt233 改（2026-11-10）：默认同步教程占位；只读教程任务可显式跳过。
    if "--no-tutorial" not in sys.argv and "--out" not in sys.argv:
        sync_r146e_tutorial_placeholders()
